import itertools,math

def weights(labels,scores,rho):
 groups={g:[i for i,x in enumerate(labels) if x==g] for g in range(4)}
 groups={g:ix for g,ix in groups.items() if ix}
 k=len(groups)
 w=[0.0]*len(labels);u=[0.0]*len(labels);free=[0.0]*len(labels)
 for ix in groups.values():
  maximum=max(scores[i] for i in ix)
  e=[math.exp(scores[i]-maximum) for i in ix]
  denom=sum(e)
  for i,v in zip(ix,e):
   u[i]=1.0/(k*len(ix));free[i]=v/(k*denom)
   w[i]=(1-rho)*free[i]+rho*u[i]
 return w,u,free,groups

def ent(w):return -sum(x*math.log(x) for x in w if x>0)
def close(a,b):assert abs(a-b)<2e-10,(a,b)
count=0
for length in range(5):
 for labels in itertools.product(range(-1,4),repeat=length):
  for scores in ([0.0]*length,[2.3*i-4 for i in range(length)],[(-1)**i*10000.0 for i in range(length)]):
   a,u,free,groups=weights(labels,scores,0.5)
   z,_,_,_=weights(labels,scores,0.0)
   assert z==free
   close(sum(a),float(bool(groups)))
   for g,ix in groups.items():close(sum(a[i] for i in ix),1/len(groups))
   assert all(a[i]>=0.5*u[i]-1e-12 for i in range(length))
   assert all(a[i]==0 for i,x in enumerate(labels) if x==-1)
   close(sum(abs(a[i]-u[i]) for i in range(length)),0.5*sum(abs(free[i]-u[i]) for i in range(length)))
   assert ent(a)>=ent(free)-1e-12
   assert ent(a)<=ent(u)+1e-12
   close(sum(abs(a[i]-free[i]) for i in range(length)),0.5*sum(abs(free[i]-u[i]) for i in range(length)))
   rev=weights(labels[::-1],scores[::-1],0.5)[0]
   for x,y in zip(a,rev[::-1]):close(x,y)
   shift=weights(labels,[s+(x+1)*7 for s,x in zip(scores,labels)],0.5)[0]
   for x,y in zip(a,shift):close(x,y)
   pad=weights(labels+(-1,),list(scores)+[1e10],0.5)[0]
   assert pad[-1]==0
   for x,y in zip(a,pad[:-1]):close(x,y)
   count+=1
# Interior score sensitivity retains a learnable path in both rho cells.
labels=(0,0,0,1);scores=[-0.7,0.2,1.1,-0.3]
for rho in (0.0,0.5):
 w,u,free,groups=weights(labels,scores,rho)
 eps=1e-5
 for j in range(3):
  plus=scores[:];minus=scores[:];plus[j]+=eps;minus[j]-=eps
  wp=weights(labels,plus,rho)[0];wm=weights(labels,minus,rho)[0]
  for i in range(3):
   pg=free[i]*len(groups);qg=free[j]*len(groups)
   expected=(1-rho)/len(groups)*pg*((1.0 if i==j else 0.0)-qg)
   assert abs((wp[i]-wm[i])/(2*eps)-expected)<1e-10
 assert abs((weights(labels,[scores[0]+eps]+scores[1:],rho)[0][0]-w[0])/eps)>1e-3
print('Passed',count,'scalar histories/score patterns: mass, coverage floor, entropy, exact L1 contraction, padding, permutation, group-offset invariance, floor0 identity; interior finite-difference score sensitivity passed.')
print('These checks verify algebra only; they do not run Torch, training, autograd or the host scorer.')
PY"

